import { http, HttpResponse } from 'msw'

import examples from '../month-end-examples.json'

/**
 * Month end's test handlers, BUILT FROM THE SERVER'S GOLDEN ANSWERS (MD48) -- `src/test/month-end-examples.json`,
 * generated by the server from invented lists and invented workplaces and copied here byte for byte. A handler here
 * answers what the running server answered, not what somebody typed, so the client's tests and the server agree on
 * the server's day. Nothing in the file is SASBO's (MD57).
 *
 * Like every shared handler of this suite it is OPTED INTO, never global: a test says which routes it depends on with
 * `server.use(...monthEndHandlers())` or a single `monthEndAnswer(route)`.
 */
export const monthEndExamples = examples

/** A route as the server writes it -- `/api/members/{id}/status` -- as MSW matches it: `/api/members/:id/status`. */
export const mswPath = (path) => path.replace(/\{(\w+)\}/g, ':$1')

const handlerFor = (route, example) => {
  const [method, path] = route.split(' ')
  return http[method.toLowerCase()](`*${mswPath(path)}`, () =>
    HttpResponse.json(example.body, { status: example.status }))
}

/** Every route of the arc, answered as the server answered it. */
export const monthEndHandlers = () =>
  Object.entries(examples.answers).map(([route, example]) => handlerFor(route, example))

/** One route -- `'GET /api/workplaces'` -- answered as the server answered it. */
export const monthEndAnswer = (route) => {
  const example = examples.answers[route]
  if (!example) throw new Error(`month-end-examples.json has no answer for ${route}`)
  return handlerFor(route, example)
}

/** The server's body for a route, to assert against. */
export const monthEndBody = (route) => examples.answers[route]?.body

/** A route answering one of the arc's refusals, exactly as the server answers it. */
export const monthEndRefusal = (code, route) => {
  const example = examples.refusals[code]
  if (!example) throw new Error(`month-end-examples.json has no refusal ${code}`)
  return handlerFor(route, example)
}
